package com.example.app03.application.service; import com.example.app03.domain.entity.Lead; import com.example.app03.infrastructure.repository.LeadRepository; import java.util.List; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; @Service public class LeadService { private final LeadRepository repository; public LeadService(LeadRepository repository) { this.repository=repository; } @Transactional(readOnly=true) public List<Lead> list() { return repository.findAll(); } @Transactional public Lead create(Lead e) { return repository.save(e); } }
